{
  "opening": "This release introduces significant enhancements to the glom library, focusing on new specification types, improved CLI capabilities, and better introspection. The following requirements define the observable behavior of these changes for developers integrating or upgrading.",
  "requirements": [
    {
      "id": "m15",
      "text": "The command-line interface must accept Python expressions as specifications and targets, allowing full Python syntax rather than being limited to AST literals."
    },
    {
      "id": "m29",
      "text": "When using tuple steps in a specification, nested scopes must be created such that variable captures within inner tuples do not leak into outer scopes."
    },
    {
      "id": "m33",
      "text": "The string representation of Invoke expressions should be concise, omitting internal argument details to provide a cleaner output."
    },
    {
      "id": "m34",
      "text": "Public documentation and module attributes should expose 'constants' instead of 'consts', ensuring consistent naming for exported configuration values."
    },
    {
      "id": "m44",
      "text": "The Fill specifier must provide a meaningful string representation that clearly indicates its purpose and arguments when printed or logged."
    },
    {
      "id": "m45",
      "text": "The Assign specifier and its convenience function must provide a clear string representation showing the assigned key and value."
    },
    {
      "id": "m46",
      "text": "The Coalesce specifier must provide a readable string representation that displays the sequence of alternatives being tried."
    },
    {
      "id": "m47",
      "text": "All public specifier types, including Auto and Check, must implement reasonable string representations that aid in debugging and inspection."
    }
  ],
  "closing": "Please ensure all public APIs behave as described above before tagging this release."
}
